// Config injected at RUNTIME by /config.js (generated by the container
// entrypoint, see frontend/docker-entrypoint.d/40-config.sh). One frontend
// image serves every environment: values change with .env, not the build.
interface RuntimeEnv {
  apiUrl?: string;
  version?: string;
  date?: string;
}

interface Window {
  __ENV__?: RuntimeEnv;
}
